import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    if n == 0:
        return

    arr = list(map(int, data[1:n+1]))

    for i in range(n - 1):
        for j in range(n - 1 - i):
            if arr[j] > arr[j + 1]:
                arr[j], arr[j + 1] = arr[j + 1], arr[j]
        print(' '.join(map(str, arr)))

if __name__ == "__main__":
    main()
